window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a182250eeacff46e"]={"versions": [{"id": "FIG-a182250eeacff46e", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram) zur Spezifikation eines algorithmischen Teilschritts.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Ausführungsschritts „Write CRC“ (<code>[PRS_E2E_00514]</code>) innerhalb der E2E-Bibliothek (AUTOSAR Foundation / Classic / Adaptive Platform). Der Schritt ist identischer Bestandteil der Sender-Schutzfunktion <code>E2E_P11Protect()</code> sowie der Gateway-Weiterleitungsfunktion <code>E2E_P11Forward()</code> für das E2E-Profil 11 (Safety-Integritätsschutz bis ASIL D gemäß ISO 26262).</li>\n<li><strong>Funktionaler Kontext:</strong> Unmittelbarer Folgeschritt nach der Prüfsummenberechnung („Compute CRC“, Figure 6.98 / <code>[PRS_E2E_00513]</code>). Er überführt das berechnete 1-Byte-Zwischenergebnis in die Nutzdaten-PDU.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Funktionskontexte:</strong></li>\n<li><code>E2E_P11Protect()</code>: Hauptfunktion zur E2E-Absicherung von Sende-PDUs vor der Übergabe an unterlagerte Schichten (z. B. PduR, Com).</li>\n<li><code>E2E_P11Forward()</code>: Gateway-Funktion zur Re-Protektion weitergeleiteter PDUs bei Modifikation oder Counter-Aktualisierung.</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Config</code> (Typ <code>E2E_P11ConfigType*</code>, In-Parameter): Enthält u. a. <code>CRCOffset</code> (<code>uint16</code>, Offset der CRC innerhalb des Datenstroms in Bits).</li>\n<li><code>Data</code> (<code>uint8*</code>, In/Out-Puffer): Zeiger auf das Nutzdaten-Array der PDU.</li>\n<li><code>ComputedCRC</code> (<code>uint8</code>, lokale Variable): Die im vorgelagerten Schritt via <code>Crc_CalculateCRC8</code> ermittelte 8-Bit-Prüfsumme.</li>\n<li><strong>Beziehungen & Stereotypen:</strong></li>\n<li>Direkte Zuweisung/Serialisierung auf Puffer-Ebene: <code>Data[Config-&gt;CRCOffset / 8] = ComputedCRC</code>.</li>\n<li>Kardinalität: 1 Byte Schreibzugriff an exakt einer berechneten Byte-Adresse.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontrollfluss:</strong> Streng sequenziell und deterministisch; keine bedingten Verzweigungen (<code>Decision Nodes</code>) oder asynchronen Pfade.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt (Initial Node):</strong> Aktivierung unmittelbar nach Berechnung von <code>ComputedCRC</code>.</li>\n<li><strong>Index-Transformation & Schreiboperation (Action):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Umrechnung des Bit-Offsets in einen Byte-Index: $\\text{ByteOffset} = \\text{Config}\\to\\text{CRCOffset} / 8$.</li>\n<li>Atomares Kopieren des 8-Bit-Werts <code>ComputedCRC</code> an die Zieladresse <code>Data[ByteOffset]</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss (Activity Final Node):</strong> Beendigung des Schritts; die PDU ist bezüglich der CRC vollständig geschützt.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerbehandlung / Callbacks:</strong> Keine lokalen Verzweigungen oder Det/Dem-Aufrufe innerhalb dieses Schritts. Plausibilitätsprüfungen der Offsets erfolgen zwingend in den vorgeschalteten Validierungsphasen der aufrufenden APIs.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität:</strong> Verbindliche Implementierungsvorschrift gemäß <code>[PRS_E2E_00514]</code> (basierend auf <code>RS_E2E_08539</code>).</li>\n<li><strong>Byte-Alignment-Constraint:</strong> <code>Config-&gt;CRCOffset</code> muss in der System-/E2E-Konfiguration zwingend auf ein Byte ausgerichtet sein ($\\text{CRCOffset} \\pmod 8 == 0$). E2E Profile 11 unterstützt keine Bit-Shifted-CRCs über Byte-Grenzen hinweg.</li>\n<li><strong>Speichersicherheit & Bounds Checking:</strong> Da die Operation ungeprüft auf <code>Data[Config-&gt;CRCOffset / 8]</code> schreibt, muss der Pre-Check in <code>E2E_P11Protect()</code> / <code>E2E_P11Forward()</code> zwingend sicherstellen, dass gilt:</li>\n</ul>\n<p class=\"fig-p\">$$\\frac{\\text{Config}\\to\\text{CRCOffset}}{8} < \\text{Length}$$</p>\n<p class=\"fig-p\">Ein Konfigurationsfehler führt andernfalls zu Out-of-Bounds-Memory-Corruption.</p>\n<ul class=\"fig-list\">\n<li><strong>Reentranz:</strong> Beide Funktionen sind reentrant für disjunkte PDU-Puffer und Instanzen (<code>State</code>/<code>Config</code>). Da der Puffer <code>Data[]</code> direkt in-place modifiziert wird, ist bei geteilter Puffer-Nutzung applikationsseitig für exklusiven Zugriff (Exclusive Area / Mutex) zu sorgen.</li>\n</ul>"}, {"id": "FIG-3989b4c56c5ccbf6", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram) zur Spezifikation eines algorithmischen Teilschritts.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Ausführungsschritts „Write CRC“ (<code>[PRS_E2E_00514]</code>) innerhalb der E2E-Bibliothek (AUTOSAR Foundation / Classic / Adaptive Platform). Der Schritt ist identischer Bestandteil der Sender-Schutzfunktion <code>E2E_P11Protect()</code> sowie der Gateway-Weiterleitungsfunktion <code>E2E_P11Forward()</code> für das E2E-Profil 11 (Safety-Integritätsschutz bis ASIL D gemäß ISO 26262).</li>\n<li><strong>Funktionaler Kontext:</strong> Unmittelbarer Folgeschritt nach der Prüfsummenberechnung („Compute CRC“, Figure 6.98 / <code>[PRS_E2E_00513]</code>). Er überführt das berechnete 1-Byte-Zwischenergebnis in die Nutzdaten-PDU.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufende Funktionskontexte:</strong></li>\n<li><code>E2E_P11Protect()</code>: Hauptfunktion zur E2E-Absicherung von Sende-PDUs vor der Übergabe an unterlagerte Schichten (z. B. PduR, Com).</li>\n<li><code>E2E_P11Forward()</code>: Gateway-Funktion zur Re-Protektion weitergeleiteter PDUs bei Modifikation oder Counter-Aktualisierung.</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Config</code> (Typ <code>E2E_P11ConfigType*</code>, In-Parameter): Enthält u. a. <code>CRCOffset</code> (<code>uint16</code>, Offset der CRC innerhalb des Datenstroms in Bits).</li>\n<li><code>Data</code> (<code>uint8*</code>, In/Out-Puffer): Zeiger auf das Nutzdaten-Array der PDU.</li>\n<li><code>ComputedCRC</code> (<code>uint8</code>, lokale Variable): Die im vorgelagerten Schritt via <code>Crc_CalculateCRC8</code> ermittelte 8-Bit-Prüfsumme.</li>\n<li><strong>Beziehungen & Stereotypen:</strong></li>\n<li>Direkte Zuweisung/Serialisierung auf Puffer-Ebene: <code>Data[Config-&gt;CRCOffset / 8] = ComputedCRC</code>.</li>\n<li>Kardinalität: 1 Byte Schreibzugriff an exakt einer berechneten Byte-Adresse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontrollfluss:</strong> Streng sequenziell und deterministisch; keine bedingten Verzweigungen (<code>Decision Nodes</code>) oder asynchronen Pfade.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt (Initial Node):</strong> Aktivierung unmittelbar nach Berechnung von <code>ComputedCRC</code>.</li>\n<li><strong>Index-Transformation & Schreiboperation (Action):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Umrechnung des Bit-Offsets in einen Byte-Index: $\\text{ByteOffset} = \\text{Config}\\to\\text{CRCOffset} / 8$.</li>\n<li>Atomares Kopieren des 8-Bit-Werts <code>ComputedCRC</code> an die Zieladresse <code>Data[ByteOffset]</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss (Activity Final Node):</strong> Beendigung des Schritts; die PDU ist bezüglich der CRC vollständig geschützt.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Fehlerbehandlung / Callbacks:</strong> Keine lokalen Verzweigungen oder Det/Dem-Aufrufe innerhalb dieses Schritts. Plausibilitätsprüfungen der Offsets erfolgen zwingend in den vorgeschalteten Validierungsphasen der aufrufenden APIs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Anforderungskonformität:</strong> Verbindliche Implementierungsvorschrift gemäß <code>[PRS_E2E_00514]</code> (basierend auf <code>RS_E2E_08539</code>).</li>\n<li><strong>Byte-Alignment-Constraint:</strong> <code>Config-&gt;CRCOffset</code> muss in der System-/E2E-Konfiguration zwingend auf ein Byte ausgerichtet sein ($\\text{CRCOffset} \\pmod 8 == 0$). E2E Profile 11 unterstützt keine Bit-Shifted-CRCs über Byte-Grenzen hinweg.</li>\n<li><strong>Speichersicherheit & Bounds Checking:</strong> Da die Operation ungeprüft auf <code>Data[Config-&gt;CRCOffset / 8]</code> schreibt, muss der Pre-Check in <code>E2E_P11Protect()</code> / <code>E2E_P11Forward()</code> zwingend sicherstellen, dass gilt:</li>\n</ul>\n<p class=\"fig-p\">$$\\frac{\\text{Config}\\to\\text{CRCOffset}}{8} < \\text{Length}$$</p>\n<p class=\"fig-p\">Ein Konfigurationsfehler führt andernfalls zu Out-of-Bounds-Memory-Corruption.</p>\n<ul class=\"fig-list\">\n<li><strong>Reentranz:</strong> Beide Funktionen sind reentrant für disjunkte PDU-Puffer und Instanzen (<code>State</code>/<code>Config</code>). Da der Puffer <code>Data[]</code> direkt in-place modifiziert wird, ist bei geteilter Puffer-Nutzung applikationsseitig für exklusiven Zugriff (Exclusive Area / Mutex) zu sorgen.</li>\n</ul>"}], "trans": [{"from": "FIG-a182250eeacff46e", "to": "FIG-3989b4c56c5ccbf6", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Aktionsknoten „Write CRC“</strong>: Der Text innerhalb der Aktion wurde durch einen Zeilenumbruch nach <code>Config-</code> auf zwei Zeilen aufgeteilt (<code>Data[Config-</code> / <code>&gt;CRCOffset/8]</code>).</li>\n<li><strong>Kopfbereich / Diagrammbegrenzung</strong>: Die versehentlich am oberen Bildrand hineingeragte Textzeile der umgebenden Spezifikation („ard() shall behave as shown in Figure 6.99...“) wurde entfernt.</li>\n</ul>"}]};
